#include "gig/itch/context.hpp"
#include <algorithm>
#include <iostream>
#include <sstream>
#include <string>
#include <type_traits>
#include <vector>
using namespace gig::itch;
namespace {
using Bytes=std::vector<std::byte>;
std::string hex(std::span<const std::byte> bytes){constexpr char d[]="0123456789abcdef";std::string out;for(auto b:bytes){auto n=std::to_integer<unsigned>(b);out+=d[n>>4];out+=d[n&15];}return out;}
std::string hex(std::string_view s){return hex({reinterpret_cast<const std::byte*>(s.data()),s.size()});}
template<class T>void put(Bytes&b,T value,unsigned width){const auto n=static_cast<std::uint64_t>(value);for(unsigned i=width;i>0;--i)b.push_back(static_cast<std::byte>((n>>((i-1)*8U))&255U));}
void text(Bytes&b,std::string_view s){for(auto c:s)b.push_back(static_cast<std::byte>(c));}
void add(Bytes&b,const AddOrder&v){put(b,v.order_reference.value(),8);put(b,static_cast<unsigned>(v.side),1);put(b,v.shares.value(),4);text(b,v.stock.view());put(b,v.price.value(),4);}
void execution(Bytes&b,const OrderExecuted&v){put(b,v.order_reference.value(),8);put(b,v.executed_shares.value(),4);put(b,v.match_number.value(),8);}
Bytes directory(const StockDirectory&v){Bytes b;text(b,v.stock.view());put(b,static_cast<unsigned>(v.market_category),1);put(b,static_cast<unsigned>(v.financial_status),1);put(b,v.round_lot_size,4);put(b,static_cast<unsigned>(v.round_lots_only),1);put(b,static_cast<unsigned>(v.issue_classification),1);text(b,v.issue_subtype.view());for(auto c:{v.authenticity,v.short_sale_threshold,v.ipo_flag,v.luld_tier,v.etp_flag})put(b,static_cast<unsigned>(c),1);put(b,v.etp_leverage,4);put(b,static_cast<unsigned>(v.inverse),1);return b;}
Bytes raw(const DecodedRecord&r){Bytes b;put(b,r.type,1);put(b,r.header.stock_locate.value(),2);put(b,r.header.tracking_number.value(),2);put(b,r.header.timestamp.value(),6);std::visit([&](const auto&v){using T=std::decay_t<decltype(v)>;
if constexpr(std::is_same_v<T,SystemEvent>)put(b,static_cast<unsigned>(v.event_code),1);
else if constexpr(std::is_same_v<T,StockDirectory>){auto d=directory(v);b.insert(b.end(),d.begin(),d.end());}
else if constexpr(std::is_same_v<T,AddOrder>)add(b,v);
else if constexpr(std::is_same_v<T,AddAttributedOrder>){add(b,v.order);text(b,v.attribution.view());}
else if constexpr(std::is_same_v<T,OrderExecuted>)execution(b,v);
else if constexpr(std::is_same_v<T,OrderExecutedWithPrice>){execution(b,v.execution);put(b,static_cast<unsigned>(v.printable),1);put(b,v.execution_price.value(),4);}
else if constexpr(std::is_same_v<T,OrderCancel>){put(b,v.order_reference.value(),8);put(b,v.cancelled_shares.value(),4);}
else if constexpr(std::is_same_v<T,OrderDelete>)put(b,v.order_reference.value(),8);
else if constexpr(std::is_same_v<T,OrderReplace>){put(b,v.original_reference.value(),8);put(b,v.new_reference.value(),8);put(b,v.shares.value(),4);put(b,v.price.value(),4);}
else if constexpr(std::is_same_v<T,Trade>){put(b,v.order_reference.value(),8);put(b,static_cast<unsigned>(v.side),1);put(b,v.shares.value(),4);text(b,v.stock.view());put(b,v.price.value(),4);put(b,v.match_number.value(),8);}
else if constexpr(std::is_same_v<T,CrossTrade>){put(b,v.shares.value(),8);text(b,v.stock.view());put(b,v.cross_price.value(),4);put(b,v.match_number.value(),8);put(b,static_cast<unsigned>(v.cross_type),1);}
else if constexpr(std::is_same_v<T,BrokenTrade>)put(b,v.match_number.value(),8);
},r.message);return b;}
void order(const OrderState&o){std::cout<<o.reference.value()<<','<<o.locate.value()<<','<<hex(o.stock.view())<<','<<static_cast<unsigned>(o.side)<<','<<o.remaining.value()<<','<<o.resting_price.value()<<','<<(o.attribution?hex(o.attribution->view()):"-")<<','<<o.arrival.value()<<','<<o.active;}
void optional_order(const std::optional<OrderState>&o){if(o)order(*o);else std::cout<<'-';}
void provenance(const Provenance&p){std::cout<<static_cast<unsigned>(p.origin)<<','<<(p.source?hex(p.source->view()):"-")<<','<<(p.generator_seed?std::to_string(*p.generator_seed):"-")<<','<<(p.sha256?hex(*p.sha256):"-");}
template<class T>void optional_number(const std::optional<T>&n){if(n)std::cout<<*n;else std::cout<<'-';}
void outcome(const ContextResult&r,const SourceContext&c){const auto&e=r.error;std::cout<<static_cast<unsigned>(r.status)<<','<<static_cast<unsigned>(e.code)<<','<<e.field<<','<<e.expected<<','<<e.actual<<','<<e.location.frame_offset.value()<<','<<e.location.payload_offset.value()<<','<<e.location.ordinal.value()<<','<<static_cast<unsigned>(e.source_error.code)<<','<<e.source_error.offset.value()<<','<<e.source_error.field<<','<<e.source_error.expected<<','<<e.source_error.actual<<"|N:";
if(r.record){const auto&n=*r.record;std::cout<<static_cast<unsigned>(n.kind)<<','<<static_cast<unsigned>(n.integration)<<','<<hex(raw(n.source))<<','<<n.source.location.frame_offset.value()<<','<<n.source.location.payload_offset.value()<<','<<n.source.location.ordinal.value()<<';';provenance(n.source.provenance);std::cout<<';'<<hex(n.manifest.source.view())<<','<<hex(n.manifest.session.view())<<','<<static_cast<unsigned>(n.manifest.initialization)<<',';provenance(n.manifest.provenance);std::cout<<';';optional_order(n.before);std::cout<<';';optional_order(n.after);std::cout<<';';if(n.observed_execution_price)std::cout<<n.observed_execution_price->value();else std::cout<<'-';std::cout<<';';if(n.printable)std::cout<<static_cast<unsigned>(*n.printable);else std::cout<<'-';std::cout<<';';optional_number(n.price_ticks);std::cout<<';';optional_number(n.quantity_lots);std::cout<<';'<<n.initialization_incomplete;const auto&p=n.policy;std::cout<<";P:"<<n.normalization_version<<','<<p.max_directories<<','<<p.max_lifetime_orders<<','<<p.max_matches<<','<<p.memory_budget_bytes<<','<<p.first_location.frame_offset.value()<<','<<p.first_location.payload_offset.value()<<','<<p.first_location.ordinal.value()<<','<<p.require_monotonic_timestamps<<','<<p.require_intraday_timestamps<<','<<p.require_lifecycle_order<<','<<p.allow_equal_cancel<<','<<p.price_quantum<<','<<p.lot_size;}else std::cout<<'-';
const auto&s=c.summary();std::cout<<"|S:"<<s.accepted_records<<','<<s.directories<<','<<s.lifetime_orders<<','<<s.matches<<','<<s.active_orders<<',';if(s.last_location)std::cout<<s.last_location->frame_offset.value()<<','<<s.last_location->payload_offset.value()<<','<<s.last_location->ordinal.value();else std::cout<<"-,-,-";std::cout<<',';if(s.last_timestamp)std::cout<<s.last_timestamp->value();else std::cout<<'-';std::cout<<','<<s.initialization_incomplete<<','<<s.finished<<','<<s.source_complete<<','<<s.bounded_prefix<<','<<s.session_incomplete<<','<<static_cast<unsigned>(s.finish_error)<<"|D:";for(const auto&d:c.directories())std::cout<<d.locate.value()<<','<<hex(directory(d.directory))<<'/';std::cout<<"|O:";for(const auto&o:c.orders()){order(o);std::cout<<'/';}std::cout<<"|M:";for(const auto&m:c.matches())std::cout<<m.number.value()<<','<<m.locate.value()<<','<<static_cast<unsigned>(m.kind)<<','<<m.broken<<'/';}
}
int main(){std::string line;while(std::getline(std::cin,line)){std::istringstream in(line);ContextPolicy p;unsigned flags{};in>>p.price_quantum>>p.lot_size>>p.max_lifetime_orders>>p.max_matches>>flags;p.max_directories=8;p.require_monotonic_timestamps=(flags&1U)!=0;p.require_intraday_timestamps=(flags&2U)!=0;p.allow_equal_cancel=(flags&4U)!=0;Provenance prov;prov.origin=Origin::synthetic;prov.source=SourceIdentity::make("synthetic-context").data;prov.generator_seed=1729;std::array<std::byte,32> digest{};for(std::size_t i=0;i<digest.size();++i)digest[i]=static_cast<std::byte>(i);prov.sha256=digest;SourceManifest manifest{*prov.source,*SourceIdentity::make("synthetic-day").data,prov,Initialization::synthetic_history_declared};auto context=SourceContext::create(manifest,p);if(!context){std::cout<<"CREATE_ERROR,"<<static_cast<unsigned>(context.error.code)<<'\n';continue;}std::uint64_t offset=0,ordinal=0;std::string encoded;bool first=true;while(in>>encoded){if(encoded.starts_with('!')){context.data->finish(static_cast<ContextEnd>(std::stoul(encoded.substr(1))));ContextResult result;result.status=ContextStatus::accepted;if(!first)std::cout<<"~";first=false;outcome(result,*context.data);continue;}Bytes bytes;if(encoded!="-")for(std::size_t i=0;i<encoded.size();i+=2)bytes.push_back(static_cast<std::byte>(std::stoul(encoded.substr(i,2),nullptr,16)));auto result=context.data->apply(bytes,{ByteOffset{offset},ByteOffset{offset+2},RecordOrdinal{ordinal}},prov);if(!first)std::cout<<"~";first=false;outcome(result,*context.data);if(result.committed()){offset+=bytes.size()+2;++ordinal;}}std::cout<<'\n';}}
